import { defineUi } from '@/lib/component'
import { svgPatternDefs, type PaperTileName } from '@/lib/ink/textures'

export const PAPER_DEF_TILES: readonly PaperTileName[] = ['fibre', 'relief', 'slip', 'kraft', 'cloud']
// 纸纹定义保持原版 SVG 标识，确保复杂纸边与纸面引用同一组纹理。
export const PaperDefs = defineUi<{ tiles?: readonly PaperTileName[] }>('PaperDefs', ['tiles'], props => () => <svg data-ll-paper-defs="" width={0} height={0} style={{ position: 'absolute' }} aria-hidden="true" focusable="false"><defs innerHTML={svgPatternDefs({ tiles: props.tiles ?? PAPER_DEF_TILES })} /></svg>)
export function ensurePaperDefs(tiles: readonly PaperTileName[]): void {
  if (typeof document === 'undefined') return
  const missing = tiles.filter(tile => !document.getElementById(`ll-tex-${tile}-img`))
  if (!missing.length) return
  const holder = document.createElement('div')
  holder.innerHTML = `<svg data-ll-paper-defs="" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs>${svgPatternDefs({ tiles: missing })}</defs></svg>`
  const svg = holder.firstElementChild
  if (svg) document.body.appendChild(svg)
}

import type { Pt, Tier } from '@/lib/ink/types'
import type { Rng } from '@/lib/ink/rng'
import { noise1 } from '@/lib/ink/noise'
import { TIERS, polyPath, simplePath, smoothClosed } from '@/lib/ink/geom'

export type EdgeKind = 'cut' | 'torn' | 'deckle' | 'crimp' | 'zig' | 'perf' | 'scallop'
export type EdgeSide = 'top' | 'right' | 'bottom' | 'left'
export type EdgeSpec = EdgeKind | Partial<Record<EdgeSide, EdgeKind>>

export const EDGE_KINDS: readonly EdgeKind[] = ['cut', 'torn', 'deckle', 'crimp', 'zig', 'perf', 'scallop']
const SIDES: readonly EdgeSide[] = ['top', 'right', 'bottom', 'left']

export function edgeSides(edge: EdgeSpec | undefined): [EdgeKind, EdgeKind, EdgeKind, EdgeKind] {
  if (!edge) return ['cut', 'cut', 'cut', 'cut']
  if (typeof edge === 'string') return [edge, edge, edge, edge]
  return SIDES.map((s) => edge[s] ?? 'cut') as [EdgeKind, EdgeKind, EdgeKind, EdgeKind]
}

export const isCutEdge = (edge: EdgeSpec | undefined): boolean => edgeSides(edge).every((k) => k === 'cut')

export function edgeName(edge: EdgeSpec | undefined): EdgeKind {
  return edgeSides(edge).find((k) => k !== 'cut') ?? 'cut'
}

interface Rough {
  b: number
  lo: number
  mid: number
  hi: number
  f0: number
  f1: number
  step: number
}
const ROUGH: Record<'cut' | 'torn' | 'deckle' | 'crimp', Rough> = {
  cut: { b: 0.55, lo: 0.16, mid: 0, hi: 0.05, f0: 0, f1: 0, step: 14 },
  crimp: { b: 1.5, lo: 0.6, mid: 0.36, hi: 0.15, f0: 0.3, f1: 0.3, step: 2.1 },
  torn: { b: 2.5, lo: 1.5, mid: 1.15, hi: 0.6, f0: 0.9, f1: 0.8, step: 1.7 },
  deckle: { b: 2.3, lo: 1.3, mid: 0.95, hi: 0.42, f0: 1.5, f1: 1, step: 1.9 },
}

const ZIG = { pitch: 8, depth: 4.2 }
const PERF = { pitch: 5.4, depth: 2.3 }
const SCALLOP = { pitch: 14 }

interface Sample {
  u: number
  e: number
  f: number
}

const NOISE_PERIODS = { lo: 22, mid: 3.2, hi: 0.9, fz: 1.1 }

function roughSide(kind: keyof typeof ROUGH, len: number, rng: Rng, amp: number): Sample[] {
  const K = ROUGH[kind]
  const lo = noise1(rng.fork('lo'), len, NOISE_PERIODS.lo)
  const mid = noise1(rng.fork('mid'), len, NOISE_PERIODS.mid)
  const hi = noise1(rng.fork('hi'), len, NOISE_PERIODS.hi)
  const fz = noise1(rng.fork('fz'), len, NOISE_PERIODS.fz)
  const cnt = Math.max(2, Math.round(len / K.step))
  const out: Sample[] = []
  for (let i = 0; i <= cnt; i++) {
    const u = (i / cnt) * len
    const fade = Math.min(1, u / 7, (len - u) / 7)
    const e = Math.max(0.15, (K.b + K.lo * lo(u) + K.mid * mid(u) + K.hi * hi(u)) * amp) * (0.35 + 0.65 * fade)
    const f = Math.max(0, K.f0 + K.f1 * fz(u)) * amp * fade
    out.push({ u, e, f })
  }
  return out
}

function zigSide(len: number, rng: Rng, amp: number): Sample[] {
  const n = Math.max(2, Math.round(len / ZIG.pitch))
  const pitch = len / n
  const jit = noise1(rng.fork('zj'), len, 30)
  const out: Sample[] = []
  for (let i = 0; i <= n; i++) {
    out.push({ u: i * pitch, e: 0.15, f: 0 })
    if (i < n) out.push({ u: (i + 0.5) * pitch, e: (ZIG.depth + 0.5 * jit((i + 0.5) * pitch)) * amp, f: 0 })
  }
  return out
}

function perfSide(len: number, rng: Rng, amp: number): Sample[] {
  const n = Math.max(2, Math.round(len / PERF.pitch))
  const pitch = len / n
  const jit = noise1(rng.fork('pj'), len, 40)
  const out: Sample[] = [{ u: 0, e: 0.3, f: 0 }]
  for (let i = 0; i < n; i++) {
    const c = (i + 0.5) * pitch
    const r = pitch * 0.4
    const depth = (PERF.depth + 0.3 * jit(c)) * amp
    for (let k = 0; k <= 6; k++) {
      const a = Math.PI * (k / 6)
      out.push({ u: c - Math.cos(a) * r, e: 0.3 + Math.sin(a) * depth, f: 0 })
    }
  }
  out.push({ u: len, e: 0.3, f: 0 })
  return out
}

function scallopSide(len: number, rng: Rng, amp: number): Sample[] {
  const n = Math.max(2, Math.round(len / SCALLOP.pitch))
  const pitch = len / n
  const R = pitch / 2
  const out: Sample[] = []
  for (let i = 0; i < n; i++) {
    const c = (i + 0.5) * pitch
    const wob = 1 + 0.05 * (rng.fork('s' + i)() - 0.5)
    for (let k = 0; k <= 12; k++) {
      const a = -Math.PI / 2 + Math.PI * (k / 12)
      out.push({ u: c + Math.sin(a) * R * 0.98, e: 0.15 + R * 0.6 * (1 - Math.cos(a)) * amp * wob, f: 0 })
    }
  }
  return out
}

function side(kind: EdgeKind, len: number, rng: Rng, amp: number): Sample[] {
  switch (kind) {
    case 'zig':
      return zigSide(len, rng, amp)
    case 'perf':
      return perfSide(len, rng, amp)
    case 'scallop':
      return scallopSide(len, rng, amp)
    default:
      return roughSide(kind, len, rng, amp)
  }
}

export interface OutlineOpts {
  amp?: number
  chamfer?: number
}

export interface Outline {
  pts: Pt[]
  rim: Pt[]
  crisp: boolean
  reach: number
  fibrous: boolean
  sides: Array<{ kind: EdgeKind; from: number; to: number }>
}

export function sheetOutline(rng: Rng, w: number, h: number, edge: EdgeSpec, o: OutlineOpts = {}): Outline {
  const amp = o.amp ?? 1
  const kinds = edgeSides(edge)
  const S = [
    side(kinds[0], w, rng.fork('top'), amp),
    side(kinds[1], h, rng.fork('right'), amp),
    side(kinds[2], w, rng.fork('bottom'), amp),
    side(kinds[3], h, rng.fork('left'), amp),
  ]
  const pts: Pt[] = []
  const rim: Pt[] = []
  let reach = 0
  const push = (p: Pt, r: Pt, f: number) => {
    pts.push(p)
    rim.push(r)
    if (f > reach) reach = f
  }
  const sides: Outline['sides'] = []
  const mark = (kind: EdgeKind, from: number) => sides.push({ kind, from, to: pts.length })
  for (const q of S[0]) push([q.u, q.e], [q.u, q.e - q.f], q.f)
  mark(kinds[0], 0)
  for (const q of S[1]) push([w - q.e, q.u], [w - q.e + q.f, q.u], q.f)
  mark(kinds[1], sides[0].to)
  for (const q of S[2]) push([w - q.u, h - q.e], [w - q.u, h - q.e + q.f], q.f)
  mark(kinds[2], sides[1].to)
  for (const q of S[3]) push([q.e, h - q.u], [q.e - q.f, h - q.u], q.f)
  mark(kinds[3], sides[2].to)
  if (o.chamfer && o.chamfer > 0) {
    chamferCorner(pts, rim, w, h, o.chamfer)
    sides.length = 0
  }
  const crisp = kinds.some((k) => k === 'zig' || k === 'perf' || k === 'scallop')
  const fibrous = kinds.some((k) => k === 'torn' || k === 'deckle')
  return { pts, rim, crisp, reach, fibrous, sides }
}

function chamferCorner(pts: Pt[], rim: Pt[], w: number, h: number, c: number): void {
  for (let i = pts.length - 1; i >= 0; i--) {
    const p = pts[i]
    if (p[0] > w - c - 0.5 && p[1] > h - c - 0.5 && p[0] + p[1] > w + h - c) {
      pts.splice(i, 1)
      rim.splice(i, 1)
    }
  }
  const at = pts.findIndex((p, i) => i > 0 && p[1] > h - 2 && p[0] < w - c && pts[i - 1][0] > p[0])
  const ins: Pt[] = [
    [w - 0.3, h - c],
    [w - c, h - 0.3],
  ]
  const j = at < 0 ? pts.length : at
  pts.splice(j, 0, ...ins)
  rim.splice(j, 0, ...ins)
}

const coarse = (tier: Tier) => ({ ...TIERS[tier], tol: TIERS[tier].tol * 1.75 })

export function outlinePath(o: Outline, which: 'body' | 'rim', tier: Tier = 'lo'): string {
  const pts = which === 'body' ? o.pts : o.rim
  if (o.crisp) return which === 'body' ? simplePath(pts, { ...TIERS[tier], tol: TIERS[tier].tol * 0.8 }) : polyPath(pts, 10)
  return smoothClosed(pts, coarse(tier))
}

export function sideInsets(o: Outline, w: number, h: number, chamfer = 0): [number, number, number, number] {
  const sum = [0, 0, 0, 0]
  const cnt = [0, 0, 0, 0]
  for (const [x, y] of o.pts) {
    if (chamfer && x > w - chamfer - 1 && y > h - chamfer - 1) continue
    const d = [y, w - x, h - y, x]
    let k = 0
    for (let i = 1; i < 4; i++) if (d[i] < d[k]) k = i
    sum[k] += d[k]
    cnt[k]++
  }
  return sum.map((v, i) => Math.round((cnt[i] ? v / cnt[i] : 0.5) * 10) / 10) as [number, number, number, number]
}

export function edgeInset(edge: EdgeSpec | undefined): number {
  const k = edgeSides(edge)
  let m = 0.6
  for (const kind of k) {
    const v = kind === 'torn' ? 4.5 : kind === 'deckle' ? 4.2 : kind === 'crimp' ? 2.6 : kind === 'zig' ? ZIG.depth + 1 : kind === 'perf' ? PERF.depth + 1 : kind === 'scallop' ? SCALLOP.pitch * 0.4 : 0.6
    if (v > m) m = v
  }
  return m
}

import { tileOffsets, type SheetShadowKind } from '@/lib/ink/paper/shadows'
import { STICKY_VEIL, TOOTH_TILES, stockOf, type StockName } from '@/lib/ink/paper/stocks'
import type { PaperTileName } from '@/lib/ink/textures'

export interface FaceSpec {
  d: string
  evenodd?: boolean
  stock: StockName
  seed: number
  veil?: false
  paper?: false
  cast?: {
    kind: SheetShadowKind
    inset: readonly [number, number, number, number]
    radius?: readonly [number, number, number, number]
  }
}

const MARK = /<!--ll-face:(.*?)-->/gs

export function faceMark(spec: FaceSpec): string {
  return `<!--ll-face:${JSON.stringify(spec).replace(/--/g, '-\\u002d')}-->`
}

export function shadowMark(kind: SheetShadowKind, radius: readonly [number, number, number, number], inset: readonly [number, number, number, number] = [0, 0, 0, 0]): string {
  return faceMark({ d: 'M0 0', stock: 'paper', seed: 0, paper: false, cast: { kind, inset, radius } })
}

export function splitFaces(markup: string): Array<string | FaceSpec> {
  const out: Array<string | FaceSpec> = []
  let last = 0
  for (const m of markup.matchAll(MARK)) {
    if (m.index > last) out.push(markup.slice(last, m.index))
    out.push(JSON.parse(m[1]) as FaceSpec)
    last = m.index + m[0].length
  }
  if (last < markup.length) out.push(markup.slice(last))
  return out
}

export const hasFace = (markup: string): boolean => markup.includes('<!--ll-face:')

export function tilesOf(stocks: Iterable<StockName>): PaperTileName[] {
  const names = new Set<PaperTileName>()
  for (const s of stocks) for (const [t] of TOOTH_TILES[stockOf(s).tooth]) names.add(t as PaperTileName)
  return [...names]
}

export function faceLook(stock: StockName, seed: string | number, veil = true): { className: string; vars: Record<string, string> } {
  const S = stockOf(stock)
  const vars: Record<string, string> = {}
  if (S.tooth === 'none') {
    vars['--ll-tex-paper'] = 'var(--ll-tex-cloud)'
    vars['--ll-tex-paper-size'] = '720px 720px'
    vars['--ll-tex-paper-pos'] = tileOffsets(seed, [[720, 720]])
  } else {
    vars['--ll-tex-paper-pos'] = tileOffsets(seed, TOOTH_TILES[S.tooth].map(([, w, h]) => [w, h] as const))
  }
  if (S.gum && veil) vars['--ll-veil'] = `${Math.round(STICKY_VEIL * 100)}%`
  if (!S.stockClass) vars['--ll-stock'] = S.color
  return { className: [S.stockClass, S.toothClass].filter(Boolean).join(' '), vars }
}

export function faceClip(spec: Pick<FaceSpec, 'd' | 'evenodd'>, dx = 0, dy = 0): string {
  return `path(${spec.evenodd ? 'evenodd, ' : ''}'${dx || dy ? translatePath(spec.d, dx, dy) : spec.d}')`
}

const num = (v: number) => String(Math.round(v * 100) / 100)
const ARITY: Record<string, number> = { m: 2, l: 2, h: 1, v: 1, c: 6, s: 4, q: 4, t: 2, a: 7 }

interface Seg {
  cmd: string
  args: number[]
}

function parsePath(d: string): Seg[] | null {
  const tokens = d.match(/[a-zA-Z]|-?\d*\.?\d+(?:e[-+]?\d+)?/g) ?? []
  const out: Seg[] = []
  let cmd = ''
  let i = 0
  while (i < tokens.length) {
    if (/[a-zA-Z]/.test(tokens[i])) {
      cmd = tokens[i++]
      if (cmd === 'z' || cmd === 'Z') {
        out.push({ cmd, args: [] })
        continue
      }
    }
    const n = ARITY[cmd.toLowerCase()]
    if (!n || i + n > tokens.length) return null
    const args = tokens.slice(i, i + n).map(Number)
    if (args.some((x) => Number.isNaN(x))) return null
    i += n
    out.push({ cmd, args })
    if (cmd === 'M') cmd = 'L'
    else if (cmd === 'm') cmd = 'l'
  }
  return out
}

export function translatePath(d: string, dx: number, dy: number): string {
  const m = /^\s*M\s*(-?(?:\d+\.?\d*|\.\d+))[\s,]*(-?(?:\d+\.?\d*|\.\d+))/.exec(d)
  if (m) {
    const rest = d.slice(m[0].length)
    if (!/[A-Z]/.test(rest)) return `M${num(+m[1] + dx)} ${num(+m[2] + dy)}${/^[.\d-]/.test(rest) ? ' ' : ''}${rest}`
  }
  const segs = parsePath(d)
  if (!segs) return d
  let last = ''
  return segs
    .map(({ cmd, args }, k) => {
      const a = [...args]
      const L = cmd.toLowerCase()
      if (cmd === cmd.toUpperCase() || (k === 0 && cmd === 'm')) {
        if (L === 'h') a[0] += dx
        else if (L === 'v') a[0] += dy
        else if (L === 'a') (a[5] += dx), (a[6] += dy)
        else for (let j = 0; j < a.length; j += 2) (a[j] += dx), (a[j + 1] += dy)
      }
      const same = cmd === last && L !== 'm'
      last = cmd
      return (same ? ' ' : cmd) + a.map(num).join(' ')
    })
    .join('')
}

function arcPoints(x1: number, y1: number, rx: number, ry: number, rot: number, large: number, sweep: number, x2: number, y2: number): Array<[number, number]> {
  rx = Math.abs(rx)
  ry = Math.abs(ry)
  if (!rx || !ry || (x1 === x2 && y1 === y2)) return [[x2, y2]]
  const phi = (rot * Math.PI) / 180
  const c = Math.cos(phi), s = Math.sin(phi)
  const dx = (x1 - x2) / 2, dy = (y1 - y2) / 2
  const x1p = c * dx + s * dy, y1p = -s * dx + c * dy
  const lam = (x1p * x1p) / (rx * rx) + (y1p * y1p) / (ry * ry)
  if (lam > 1) {
    rx *= Math.sqrt(lam)
    ry *= Math.sqrt(lam)
  }
  const num2 = rx * rx * ry * ry - rx * rx * y1p * y1p - ry * ry * x1p * x1p
  const den = rx * rx * y1p * y1p + ry * ry * x1p * x1p
  const k = (large === sweep ? -1 : 1) * Math.sqrt(Math.max(0, num2 / den))
  const cxp = (k * rx * y1p) / ry, cyp = (-k * ry * x1p) / rx
  const cx = c * cxp - s * cyp + (x1 + x2) / 2, cy = s * cxp + c * cyp + (y1 + y2) / 2
  const ang = (ux: number, uy: number, vx: number, vy: number) => Math.atan2(ux * vy - uy * vx, ux * vx + uy * vy)
  const t1 = ang(1, 0, (x1p - cxp) / rx, (y1p - cyp) / ry)
  let dt = ang((x1p - cxp) / rx, (y1p - cyp) / ry, (-x1p - cxp) / rx, (-y1p - cyp) / ry)
  if (!sweep && dt > 0) dt -= 2 * Math.PI
  else if (sweep && dt < 0) dt += 2 * Math.PI
  const out: Array<[number, number]> = []
  for (let i = 1; i <= 16; i++) {
    const t = t1 + (dt * i) / 16
    out.push([cx + rx * Math.cos(t) * c - ry * Math.sin(t) * s, cy + rx * Math.cos(t) * s + ry * Math.sin(t) * c])
  }
  return out
}

export function pathBox(d: string): [number, number, number, number] {
  const segs = parsePath(d) ?? []
  let x = 0, y = 0, sx = 0, sy = 0
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity
  const see = (px: number, py: number) => {
    if (px < x0) x0 = px
    if (px > x1) x1 = px
    if (py < y0) y0 = py
    if (py > y1) y1 = py
  }
  for (const { cmd, args } of segs) {
    const rel = cmd !== cmd.toUpperCase()
    const L = cmd.toLowerCase()
    if (L === 'z') {
      x = sx
      y = sy
      continue
    }
    const ox = rel ? x : 0
    const oy = rel ? y : 0
    if (L === 'h') x = ox + args[0]
    else if (L === 'v') y = oy + args[0]
    else if (L === 'a') {
      const ex = ox + args[5], ey = oy + args[6]
      for (const [px, py] of arcPoints(x, y, args[0], args[1], args[2], args[3], args[4], ex, ey)) see(px, py)
      x = ex
      y = ey
    } else {
      for (let j = 0; j < args.length - 2; j += 2) see(ox + args[j], oy + args[j + 1])
      x = ox + args[args.length - 2]
      y = oy + args[args.length - 1]
    }
    if (L === 'm') (sx = x), (sy = y)
    see(x, y)
  }
  return Number.isFinite(x0) ? [x0, y0, x1, y1] : [0, 0, 0, 0]
}

export interface FaceSvgOptions {
  tiles?: boolean
  id?: string
}

const tok = (name: string) => `var(--ll-${name})`

export function faceSvg(spec: FaceSpec, o: FaceSvgOptions = {}): string {
  if (spec.paper === false) return ''
  const S = stockOf(spec.stock)
  const gid = `${o.id ?? 'll-fc'}${spec.seed.toString(36)}`
  const [x0, y0, x1, y1] = pathBox(spec.d)
  const R = `x="${num(x0 - 2)}" y="${num(y0 - 2)}" width="${num(x1 - x0 + 4)}" height="${num(y1 - y0 + 4)}"`
  let defs = ''
  let inner = `<rect ${R} fill="${tok(S.base)}"/>`
  if (S.tint) inner += `<rect ${R} fill="${tok(S.tint[0])}" fill-opacity="${S.tint[1]}"/>`
  if (o.tiles) {
    const offs = tileOffsets(spec.seed, TOOTH_TILES[S.tooth].map(([, w, h]) => [w, h] as const)).split(', ')
    TOOTH_TILES[S.tooth].forEach(([tile, tw, th], i) => {
      const [ox, oy] = offs[i].split(' ').map(parseFloat)
      defs += `<pattern id="${gid}t${i}" width="${tw}" height="${th}" patternUnits="userSpaceOnUse" patternTransform="translate(${num(ox)} ${num(oy)})"><use href="#ll-tex-${tile}-img"/></pattern>`
      inner += `<rect ${R} fill="url(#${gid}t${i})"/>`
    })
  }
  defs += `<linearGradient id="${gid}l" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${tok('photo')}" stop-opacity=".38"/><stop offset=".42" stop-color="${tok('photo')}" stop-opacity="0"/><stop offset="1" stop-color="${tok('ink')}" stop-opacity=".035"/></linearGradient>`
  inner += `<rect ${R} fill="url(#${gid}l)"/>`
  if (S.gum && spec.veil !== false) inner += `<rect ${R} fill="${tok(S.base)}" fill-opacity="${STICKY_VEIL}"/>`
  const rule = spec.evenodd ? ' clip-rule="evenodd"' : ''
  return `<defs>${defs}<clipPath id="${gid}c"><path d="${spec.d}"${rule}/></clipPath></defs><g clip-path="url(#${gid}c)">${inner}</g>`
}

export function renderFaces(markup: string, o: FaceSvgOptions = {}): string {
  if (!hasFace(markup)) return markup
  return splitFaces(markup)
    .map((p) => (typeof p === 'string' ? p : faceSvg(p, o)))
    .join('')
}

import { onMounted, type SVGAttributes } from 'vue'
import { defineUi, omitProps } from '@/lib/component'
import type { InkResult } from '@/lib/ink/builder'
import { ensureInkDefs } from '@/lib/ink/vue/defs'
import { useInkContext } from '@/lib/ink/vue/context'

// 艺术资源继续使用原版生成的 SVG 内容，Vue 负责属性与生命周期。
export const PropSvg = defineUi<{ res: InkResult; kind: string } & SVGAttributes>('PropSvg', ['res', 'kind'], props => {
  const context = useInkContext()
  onMounted(() => { if (!context.value.hasProvider) ensureInkDefs() })
  return () => <svg data-ink={props.kind} aria-hidden="true" focusable="false" width={props.res.w} height={props.res.h} viewBox={`0 0 ${props.res.w} ${props.res.h}`} {...omitProps(props, ['res', 'kind'])} style={[{ overflow: 'visible' }, props.style]} innerHTML={props.res.svg} />
})

import { Ink } from '@/lib/ink/builder'
import type { InkResult } from '@/lib/ink/builder'
import { n, type PaintKey } from '@/lib/ink/paint'
import { clamp, type Rng } from '@/lib/ink/rng'
import { noise1 } from '@/lib/ink/noise'
import { TAU, polyPath, resample, roundRectPoly } from '@/lib/ink/geom'
import type { Pt, Tier } from '@/lib/ink/types'

const tok = (name: string) => `var(--ll-${name})`

interface PathAttrs {
  fill?: string
  stroke?: string
  sw?: number
  op?: number
  transform?: string
  cap?: 'round' | 'butt'
  extra?: string
}
function pathTag(d: string, a: PathAttrs): string {
  let s = `<path d="${d}"`
  s += a.fill ? ` fill="${a.fill}"` : ' fill="none"'
  if (a.stroke) s += ` stroke="${a.stroke}" stroke-width="${n(a.sw ?? 1)}" stroke-linecap="${a.cap ?? 'round'}" stroke-linejoin="round"`
  if (a.op !== undefined && a.op < 0.995) s += ` ${a.stroke && !a.fill ? 'stroke' : 'fill'}-opacity="${n(a.op, 100)}"`
  if (a.transform) s += ` transform="${a.transform}"`
  if (a.extra) s += ` ${a.extra}`
  return s + '/>'
}

const num = (v: number) => n(v, 10)
const poly = (pts: readonly Pt[], close = false) => 'M' + pts.map((p) => `${num(p[0])} ${num(p[1])}`).join('L') + (close ? 'Z' : '')

const circle = (cx: number, cy: number, r: number) => `M${num(cx - r)} ${num(cy)}a${num(r)} ${num(r)} 0 1 0 ${num(2 * r)} 0a${num(r)} ${num(r)} 0 1 0 ${num(-2 * r)} 0z`

interface PropOpts {
  tier?: Tier
  calm?: boolean
}
const make = (seed: string | number, o: PropOpts) => new Ink(seed, { tier: o.tier, calm: o.calm })

export type Accent = 'tomato' | 'tangerine' | 'lemon' | 'grass' | 'teal' | 'sky' | 'grape' | 'bubblegum'

export type TapeKind = 'masking' | 'washi-dots' | 'washi-stripes' | 'washi-zigzag' | 'washi-gingham' | 'kraft' | 'clear'
export const TAPE_KINDS: readonly TapeKind[] = ['masking', 'washi-dots', 'washi-stripes', 'washi-zigzag', 'washi-gingham', 'kraft', 'clear']
export type TapeEnds = 'saw' | 'torn' | 'straight' | 'scissor'

export interface TapeOpts extends PropOpts {
  kind?: TapeKind
  length?: number
  height?: number
  ends?: TapeEnds
  color?: Accent
}

const WASHI_DEFAULT: Record<string, Accent> = { 'washi-dots': 'bubblegum', 'washi-stripes': 'tangerine', 'washi-zigzag': 'grass', 'washi-gingham': 'sky' }
const ENDS_DEFAULT: Record<TapeKind, TapeEnds> = { masking: 'saw', kraft: 'saw', clear: 'straight', 'washi-dots': 'scissor', 'washi-stripes': 'scissor', 'washi-zigzag': 'scissor', 'washi-gingham': 'scissor' }

function tapeEnd(kind: TapeEnds, x0: number, dir: 1 | -1, h: number, r: Rng): Pt[] {
  const slant = r.range(-1.6, 1.6)
  const at = (y: number, depth: number): Pt => [x0 + dir * (depth + (slant * y) / h), y]
  const out: Pt[] = []
  if (kind === 'straight') return [at(0, 0.3), at(h, 0.3)]
  if (kind === 'saw') {
    const pitch = r.range(1.7, 2.3)
    for (let y = 0, k = 0; y < h + 0.1; y += pitch, k++) out.push(at(Math.min(y, h), k % 2 ? r.range(0.8, 1.9) : 0.2))
    return out
  }
  if (kind === 'scissor') {
    const cnt = Math.max(2, Math.round(h / 4.4))
    for (let k = 0; k <= cnt * 2; k++) out.push(at((k / (cnt * 2)) * h, k % 2 ? 1.8 + r.range(-0.15, 0.15) : 0.15))
    return out
  }
  const f = noise1(r, h, 3)
  for (let y = 0; y <= h + 0.1; y += 1.2) out.push(at(Math.min(y, h), 1.3 + 1.6 * f(y)))
  return out
}

export function tape(seed: string | number, o: TapeOpts = {}): InkResult {
  const ink = make(seed, o)
  const kind = o.kind ?? 'masking'
  const w = o.length ?? 72
  const h = o.height ?? 22
  const r = ink.next('tape')
  const ends = o.ends ?? ENDS_DEFAULT[kind]
  const left = tapeEnd(ends, 0.5, 1, h, r.fork('l'))
  const right = tapeEnd(ends, w - 0.5, -1, h, r.fork('r')).reverse()
  const body = polyPath([...left, ...right], 10)
  const accent: PaintKey = o.color ?? WASHI_DEFAULT[kind] ?? 'bubblegum'
  const gid = `ll-tp${ink.seed.toString(36)}`
  ink.group({ clip: body }, () => {
    let s = ''
    switch (kind) {
      case 'masking':
        s += pathTag(`M0 0H${w}V${h}H0Z`, { fill: tok('kraft'), op: 0.2 }) + pathTag(`M0 0H${w}V${h}H0Z`, { fill: tok('tape') })
        break
      case 'kraft':
        s += pathTag(`M0 0H${w}V${h}H0Z`, { fill: tok('kraft'), op: 0.9 })
        break
      case 'clear':
        s += pathTag(`M0 0H${w}V${h}H0Z`, { fill: tok('photo'), op: 0.16 })
        break
      case 'washi-dots':
        s += pathTag(`M0 0H${w}V${h}H0Z`, { fill: tok(accent), op: 0.88 })
        break
      default:
        s += pathTag(`M0 0H${w}V${h}H0Z`, { fill: tok('photo'), op: 0.88 })
    }
    const pr = r.fork('print')
    if (kind === 'washi-dots') {
      let big = '', small = ''
      const gx = h * 0.34
      for (let row = 0, y = h * 0.2; y < h + gx; y += gx * 0.86, row++) {
        for (let x = (row % 2) * gx * 0.5 - gx * 0.2; x < w + gx; x += gx) {
          const jx = pr.gauss(0, 0.22), jy = pr.gauss(0, 0.22)
          if (row % 2) small += circle(x + jx, y + jy, h * 0.058 * pr.range(0.86, 1.14))
          else big += circle(x + jx, y + jy, h * 0.105 * pr.range(0.88, 1.12))
        }
      }
      s += pathTag(big, { fill: tok('photo'), op: 0.94 }) + pathTag(small, { fill: tok('photo'), op: 0.78 })
    } else if (kind === 'washi-stripes') {
      let a = '', b = ''
      for (let x = -h - 4; x < w + h; ) {
        const sw = pr.range(2.6, 4.8)
        const p = `M${num(x)} ${num(h + 1)}L${num(x + sw)} ${num(h + 1)}L${num(x + sw + h + 2)} -1L${num(x + h + 2)} -1Z`
        if (pr() < 0.4) b += p
        else a += p
        x += sw + pr.range(3.6, 5.6)
      }
      s += pathTag(a, { fill: tok(accent), op: 0.9 }) + pathTag(b, { fill: tok(accent), op: 0.7 })
    } else if (kind === 'washi-zigzag') {
      let zz = ''
      const amp = h * 0.075, step = h * 0.27
      for (let row = 0; row < 3; row++) {
        const y0 = h * (0.22 + row * 0.28)
        const pts: Pt[] = []
        for (let x = -step, k = 0; x < w + step; x += step, k++) pts.push([x + pr.gauss(0, 0.12), y0 + (k % 2 ? amp : -amp) + pr.gauss(0, 0.12)])
        zz += poly(pts)
      }
      s += pathTag(zz, { stroke: tok(accent), sw: h * 0.085, op: 0.92 })
    } else if (kind === 'washi-gingham') {
      const q = h / 4.4
      let hb = '', vb = ''
      for (let y = 0, i = 0; y < h + q; y += q, i++) if (i % 2 === 0) hb += `M0 ${num(y)}H${w}V${num(y + q)}H0Z`
      for (let x = pr.range(-q, 0), i = 0; x < w + q; x += q, i++) if (i % 2 === 0) vb += `M${num(x)} 0V${h}H${num(x + q)}V0Z`
      s += pathTag(hb, { fill: tok(accent), op: 0.36 }) + pathTag(vb, { fill: tok(accent), op: 0.36 })
    } else if (kind === 'kraft') {
      let dark = '', light = ''
      for (let i = 0; i < Math.round((w * h) / 26); i++) {
        const x = pr.range(-4, w), y = pr.range(0, h), L = pr.range(4, 22)
        const seg = `M${num(x)} ${num(y)}l${num(L)} ${num(pr.range(-0.5, 0.5))}`
        if (pr() < 0.55) dark += seg
        else light += seg
      }
      s += pathTag(dark, { stroke: tok('orange-text'), sw: 0.45, op: 0.2 }) + pathTag(light, { stroke: tok('photo'), sw: 0.5, op: 0.42 })
    }
    const nc = 1 + Math.floor(r.fork('crinkle')() * 2.4)
    let lit = '', dark = ''
    for (let i = 0; i < nc; i++) {
      const cr = r.fork('c' + i)
      const x = cr.range(0.15, 0.85) * w
      const sl = cr.range(-0.5, 0.5) * h
      const cw = cr.range(1.6, 4.6)
      lit += `M${num(x - sl / 2)} -1L${num(x + sl / 2)} ${h + 1}`
      dark += `M${num(x - sl / 2 + cw * 0.85)} -1L${num(x + sl / 2 + cw * 0.85)} ${h + 1}`
      s += pathTag(`M${num(x - sl / 2)} -1L${num(x + sl / 2)} ${h + 1}`, { stroke: tok('photo'), sw: cw, op: kind === 'clear' ? 0.5 : 0.2, cap: 'butt' })
    }
    s += pathTag(dark, { stroke: tok('ink'), sw: 0.7, op: kind === 'clear' ? 0.05 : 0.07, cap: 'butt' })
    s += `<linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${tok('photo')}" stop-opacity=".0"/><stop offset=".3" stop-color="${tok('photo')}" stop-opacity="${kind === 'clear' ? 0.5 : 0.24}"/><stop offset=".62" stop-color="${tok('photo')}" stop-opacity="0"/><stop offset="1" stop-color="${tok('ink')}" stop-opacity=".05"/></linearGradient>`
    s += `<rect width="${w}" height="${h}" fill="url(#${gid})"/>`
    s += pathTag(`M0 .5H${w}M0 ${num(h - 0.5)}H${w}`, { stroke: tok('tape-edge'), sw: 0.7, op: kind === 'clear' ? 1 : 0.9, cap: 'butt' })
    s += pathTag(`M0 1.7H${w}M0 ${num(h - 1.7)}H${w}`, { stroke: tok('photo'), sw: 0.6, op: 0.34, cap: 'butt' })
    if (kind === 'masking') {
      let fl = ''
      for (let i = 0; i < Math.round(w / 8); i++) fl += `M${num(r.range(2, w - 2))} ${num(r.range(2, h - 2))}l${num(r.range(1, 5))} ${num(r.range(-0.6, 0.6))}`
      s += pathTag(fl, { stroke: tok('pencil-mark'), sw: 0.4, op: 0.28 })
    }
    ink.raw(s, 'top')
  })
  ink.grow([0, 0, w, h])
  return ink.toSvg({ w, h, pad: 3 })
}

export interface ClipOpts extends PropOpts {
  height?: number
  tone?: 'steel' | Accent
  angle?: number
}

export function clip(seed: string | number, o: ClipOpts = {}): InkResult {
  const ink = make(seed, o)
  const H = o.height ?? 64
  const w = H / 3.4
  const r = ink.next('clip')
  const angle = o.angle ?? clamp(r.gauss(0, 2.4), -4, 4)
  const lw = clamp(w * 0.13, 1.1, 2.6)
  const j = () => r.gauss(0, 0.012)
  const U = (x: number, y: number) => `${num((x + j()) * w)} ${num((y + j()) * w)}`
  const rad = (v: number) => num(v * w)
  const d =
    `M${U(0, 0.95)}V${num((2.9 + j()) * w)}A${rad(0.5)} ${rad(0.5)} 0 0 0 ${U(1, 2.9)}V${num((0.4 + j()) * w)}A${rad(0.4)} ${rad(0.4)} 0 0 0 ${U(0.2, 0.4)}` +
    `V${num((2.6 + j()) * w)}A${rad(0.3)} ${rad(0.3)} 0 0 0 ${U(0.8, 2.6)}V${num((1.2 + j()) * w)}`
  const steel = o.tone === undefined || o.tone === 'steel'
  const base = steel ? tok('pencil') : tok(o.tone as Accent)
  const cx = w / 2, cy = H / 2
  let s = ''
  s += pathTag(d, { stroke: base, sw: lw })
  if (steel) s += pathTag(d, { stroke: tok('sky'), sw: lw, op: 0.16 })
  s += pathTag(d, { stroke: tok('ink'), sw: lw * 0.4, op: steel ? 0.5 : 0.28, transform: `translate(${num(lw * 0.22)} ${num(lw * 0.14)})` })
  s += pathTag(d, { stroke: tok('photo'), sw: lw * 0.32, op: 0.9, transform: `translate(${num(-lw * 0.2)} ${num(-lw * 0.22)})` })
  ink.raw(`<g transform="rotate(${n(angle)} ${num(cx)} ${num(cy)})">${s}</g>`, 'top')
  ink.grow([-lw, -lw, w + lw, H + lw])
  return ink.toSvg({ w, h: H, pad: Math.ceil(lw * 2 + Math.abs(angle) * 0.4) })
}

export interface PinOpts extends PropOpts {
  size?: number
  color?: Accent
}

export function pin(seed: string | number, o: PinOpts = {}): InkResult {
  const ink = make(seed, o)
  const D = o.size ?? 24
  const rr = D / 2
  const w = D * 1.1, h = D * 1.4
  const r = ink.next('pin')
  const cx = w / 2, cy = rr + 1
  const col = tok(o.color ?? 'tomato')
  const tilt = r.range(-6, 6)
  let s = ''
  s += pathTag(`M${num(cx - rr * 0.16)} ${num(cy + rr * 0.6)}L${num(cx + rr * 0.05)} ${num(cy + rr * 1.35)}`, { stroke: tok('pencil'), sw: rr * 0.24 })
  s += pathTag(`M${num(cx - rr * 0.2)} ${num(cy + rr * 0.6)}L${num(cx - rr * 0.01)} ${num(cy + rr * 1.33)}`, { stroke: tok('photo'), sw: rr * 0.08, op: 0.7 })
  s += `<ellipse cx="${num(cx)}" cy="${num(cy + rr * 0.56)}" rx="${num(rr * 1.02)}" ry="${num(rr * 0.4)}" fill="${tok('pencil')}"/>`
  s += `<ellipse cx="${num(cx - rr * 0.1)}" cy="${num(cy + rr * 0.5)}" rx="${num(rr * 0.9)}" ry="${num(rr * 0.28)}" fill="${tok('photo')}" fill-opacity=".5"/>`
  const dome = circle(cx, cy, rr * 0.94)
  const cid = ink.clipDef(dome)
  s += pathTag(dome, { fill: col })
  s += `<g clip-path="url(#${cid})">${pathTag(circle(cx + rr * 0.42, cy + rr * 0.46, rr * 0.98), { fill: tok('ink'), op: 0.24 })}${pathTag(circle(cx + rr * 0.5, cy + rr * 0.55, rr * 0.86), { fill: tok('ink'), op: 0.1 })}</g>`
  s += pathTag(dome, { stroke: tok('ink'), sw: 0.8, op: 0.4 })
  s += `<ellipse cx="${num(cx - rr * 0.34)}" cy="${num(cy - rr * 0.38)}" rx="${num(rr * 0.3)}" ry="${num(rr * 0.2)}" fill="${tok('photo')}" fill-opacity=".8" transform="rotate(-38 ${num(cx - rr * 0.34)} ${num(cy - rr * 0.38)})"/>`
  s += pathTag(circle(cx - rr * 0.06, cy - rr * 0.62, rr * 0.06), { fill: tok('photo'), op: 0.9 })
  ink.raw(`<g transform="rotate(${n(tilt)} ${num(cx)} ${num(cy)})">${s}</g>`, 'top')
  ink.grow([0, 0, w, h])
  return ink.toSvg({ w, h, pad: 3 })
}

export interface StapleOpts extends PropOpts {
  length?: number
  double?: boolean
}

export function staple(seed: string | number, o: StapleOpts = {}): InkResult {
  const ink = make(seed, o)
  const L = o.length ?? 20
  const w = L + 4, h = o.double ? 14 : 8
  const r = ink.next('staple')
  let s = ''
  const one = (y: number, rot: number) => {
    const x0 = 2 + r.range(-0.2, 0.2)
    let g = ''
    g += pathTag(`M${num(x0)} ${num(y)}V${num(y + 2.4)}M${num(x0 + L)} ${num(y)}V${num(y + 2.4)}`, { stroke: tok('ink'), sw: 1.5, op: 0.55 })
    g += pathTag(`M${num(x0)} ${num(y + 0.9)}H${num(x0 + L)}`, { stroke: tok('ink'), sw: 1.9, op: 0.18 })
    g += pathTag(`M${num(x0)} ${num(y)}H${num(x0 + L)}`, { stroke: tok('pencil'), sw: 2.4 })
    g += pathTag(`M${num(x0 + 0.8)} ${num(y - 0.55)}H${num(x0 + L - 0.8)}`, { stroke: tok('photo'), sw: 0.9, op: 0.9 })
    return `<g transform="rotate(${n(rot)} ${num(x0 + L / 2)} ${num(y)})">${g}</g>`
  }
  s += one(2.4, r.range(-5, 5))
  if (o.double) s += one(9, r.range(-5, 5))
  ink.raw(s, 'top')
  ink.grow([0, 0, w, h])
  return ink.toSvg({ w, h, pad: 3 })
}

export interface BinderClipOpts extends PropOpts {
  width?: number
}

export function binderClip(seed: string | number, o: BinderClipOpts = {}): InkResult {
  const ink = make(seed, o)
  const w = o.width ?? 52
  const h = w * 1.14
  const r = ink.next('binder')
  const j = () => r.gauss(0, 0.6)
  const by = h * 0.4
  ink.raw(
    pathTag(`M${num(w * 0.27)} ${num(by + 2)}C${num(w * 0.02 + j())} ${num(h * 0.16)} ${num(w * 0.16)} ${num(1.5)} ${num(w * 0.34)} ${num(1.5 + j() * 0.3)}C${num(w * 0.5)} ${num(1.5)} ${num(w * 0.5)} ${num(h * 0.2)} ${num(w * 0.45)} ${num(by + 2)}`, { stroke: tok('pencil'), sw: 2.1 }) +
      pathTag(`M${num(w * 0.55)} ${num(by + 2)}C${num(w * 0.5 + j())} ${num(h * 0.2)} ${num(w * 0.5)} ${num(1.5)} ${num(w * 0.66)} ${num(1.5 + j() * 0.3)}C${num(w * 0.84)} ${num(1.5)} ${num(w * 0.98 + j())} ${num(h * 0.16)} ${num(w * 0.73)} ${num(by + 2)}`, { stroke: tok('pencil'), sw: 2.1 }) +
      pathTag(`M${num(w * 0.25)} ${num(h * 0.16)}C${num(w * 0.2)} ${num(h * 0.06)} ${num(w * 0.3)} ${num(2.6)} ${num(w * 0.36)} ${num(2.6)}`, { stroke: tok('photo'), sw: 0.8, op: 0.85 }) +
      pathTag(`M${num(w * 0.64)} ${num(2.6)}C${num(w * 0.72)} ${num(2.6)} ${num(w * 0.8)} ${num(h * 0.06)} ${num(w * 0.79)} ${num(h * 0.14)}`, { stroke: tok('photo'), sw: 0.8, op: 0.85 }),
    'under',
  )
  const body: Pt[] = [
    [w * 0.2, by], [w * 0.8, by], [w * 0.98 + j() * 0.4, h * 0.96], [w * 0.02 + j() * 0.4, h * 0.96],
  ]
  const bodyPts = densifyRound(body, 4.5)
  ink.raw(pathTag(poly(bodyPts, true), { fill: tok('ink'), op: 0.96 }), 'wash')
  ink.stroke([...bodyPts, bodyPts[0]], 'ink.brush', { width: 0.55, wobble: 0.5 })
  ink.raw(
    pathTag(`M${num(w * 0.1)} ${num(h * 0.84)}H${num(w * 0.9)}`, { stroke: tok('pencil'), sw: 1.2, op: 0.5 }) +
      pathTag(`M${num(w * 0.24)} ${num(by + 3)}H${num(w * 0.76)}`, { stroke: tok('photo'), sw: 1.2, op: 0.3 }) +
      pathTag(`M${num(w * 0.16)} ${num(by + 6)}L${num(w * 0.07)} ${num(h * 0.8)}`, { stroke: tok('photo'), sw: 1.1, op: 0.2 }),
    'top',
  )
  ink.grow([0, 0, w, h])
  return ink.toSvg({ w, h, pad: 3 })
}

function densifyRound(v: Pt[], rad: number): Pt[] {
  const out: Pt[] = []
  const m = v.length
  for (let i = 0; i < m; i++) {
    const P = v[(i + m - 1) % m], V = v[i], N = v[(i + 1) % m]
    const l1 = Math.hypot(P[0] - V[0], P[1] - V[1]) || 1
    const l2 = Math.hypot(N[0] - V[0], N[1] - V[1]) || 1
    const rr = Math.min(rad, l1 * 0.4, l2 * 0.4)
    const a: Pt = [V[0] + ((P[0] - V[0]) / l1) * rr, V[1] + ((P[1] - V[1]) / l1) * rr]
    const b: Pt = [V[0] + ((N[0] - V[0]) / l2) * rr, V[1] + ((N[1] - V[1]) / l2) * rr]
    for (let k = 0; k <= 4; k++) {
      const t = k / 4, u = 1 - t
      out.push([u * u * a[0] + 2 * u * t * V[0] + t * t * b[0], u * u * a[1] + 2 * u * t * V[1] + t * t * b[1]])
    }
  }
  return out
}

export interface StitchOpts extends PropOpts {
  inset?: number
  radius?: number
  color?: 'marker' | 'red' | 'ink-you' | 'green' | Accent
  stitch?: number
  gap?: number
}

export function stitches(seed: string | number, w: number, h: number, o: StitchOpts = {}): InkResult {
  const ink = make(seed, o)
  const r = ink.next('stitch')
  const inset = o.inset ?? 8
  const rad = Math.min(o.radius ?? 6, (Math.min(w, h) - 2 * inset) / 2)
  const outline = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, Math.max(0, rad))
  const closed = [...outline, outline[0]]
  const rs = resample(closed, 0.8)
  const len = o.stitch ?? 7
  const gap = o.gap ?? 4
  let d = ''
  let u = r.range(0, 3)
  const at = (sArc: number): Pt => {
    const step = rs.L / (rs.X.length - 1)
    const f = Math.min(rs.X.length - 2, Math.max(0, Math.floor(sArc / step)))
    const t = Math.min(1, Math.max(0, sArc / step - f))
    return [rs.X[f] + (rs.X[f + 1] - rs.X[f]) * t, rs.Y[f] + (rs.Y[f + 1] - rs.Y[f]) * t]
  }
  while (u < rs.L - len) {
    const L = len * r.range(0.92, 1.05)
    const off = r.gauss(0, 0.3)
    const pts: Pt[] = []
    for (let k = 0; k <= 3; k++) {
      const P0 = at(u + (L * k) / 3)
      const P1 = at(Math.min(rs.L - 0.2, u + (L * k) / 3 + 0.6))
      const tx = P1[0] - P0[0], ty = P1[1] - P0[1]
      const l = Math.hypot(tx, ty) || 1
      pts.push([P0[0] - (ty / l) * off + r.gauss(0, 0.06), P0[1] + (tx / l) * off + r.gauss(0, 0.06)])
    }
    d += poly(pts)
    u += len + gap + r.gauss(0, 0.5)
  }
  const col = (o.color ?? 'marker') as PaintKey
  const id = `ll-st${ink.seed.toString(36)}`
  const line = (stroke: string, sw: number, op: number, tf: string) =>
    `<use href="#${id}" fill="none" stroke="${stroke}" stroke-width="${sw}" stroke-opacity="${op}" stroke-linecap="round" stroke-linejoin="round"${tf ? ` transform="${tf}"` : ''}/>`
  ink.raw(
    `<defs><path id="${id}" d="${d}"/></defs>` +
      line(tok('ink'), 2.1, 0.16, 'translate(.4 .8)') +
      line(tok(col), 1.8, 1, '') +
      line(tok('photo'), 0.55, 0.4, 'translate(-.3 -.35)'),
    'top',
  )
  ink.grow([0, 0, w, h])
  return ink.toSvg({ w, h, pad: 2 })
}

export interface RubberBandOpts extends PropOpts {
  color?: Accent
}

export function rubberBand(seed: string | number, w: number, h: number, o: RubberBandOpts = {}): InkResult {
  const ink = make(seed, o)
  const r = ink.next('band')
  const g = w * 0.74
  const bow = () => r.gauss(0, 0.6)
  const run = (a: number, b: number) =>
    `M${num(a + bow())} -4C${num(a)} ${num(h * 0.3)} ${num(b)} ${num(h * 0.36)} ${num(b + bow())} ${num(h * 0.5)}S${num(a)} ${num(h * 0.7)} ${num(a + bow())} ${num(h + 4)}`
  const d1 = run((w - g) / 2, (w + g) / 2)
  const d2 = run((w + g) / 2, (w - g) / 2)
  const sw = clamp(w * 0.22, 3.5, 7)
  const col = tok(o.color ?? 'tangerine')
  ink.raw(
    pathTag(d1 + d2, { stroke: tok('ink'), sw: sw + 1, op: 0.16, transform: 'translate(.8 1.6)' }) +
      pathTag(d1, { stroke: col, sw, op: 0.94 }) +
      pathTag(d2, { stroke: col, sw, op: 0.94 }) +
      pathTag(d1 + d2, { stroke: tok('ink'), sw: sw * 0.22, op: 0.2, transform: 'translate(.7 .8)' }) +
      pathTag(d1 + d2, { stroke: tok('photo'), sw: sw * 0.2, op: 0.5, transform: `translate(${num(-sw * 0.2)} ${num(-sw * 0.22)})` }),
    'top',
  )
  ink.grow([-2, -4, w + 2, h + 4])
  return ink.toSvg({ w, h, pad: 6 })
}

export interface CoffeeRingOpts extends PropOpts {
  radius?: number
}

export function coffeeRing(seed: string | number, o: CoffeeRingOpts = {}): InkResult {
  const ink = make(seed, o)
  const R0 = o.radius ?? 48
  const r = ink.next('ring')
  const p1 = r.range(0, TAU), p2 = r.range(0, TAU)
  const gapC = r.range(0, TAU), gapW = r.range(0.35, 0.8)
  const pt = (a: number, R: number): Pt => {
    const rr = R * (1 + 0.008 * Math.sin(2 * a + p1) + 0.005 * Math.sin(3 * a + p2))
    return [R0 + Math.cos(a) * rr, R0 + Math.sin(a) * rr * 0.98]
  }
  const arc = (R: number, a0: number, a1: number): Pt[] => {
    const steps = Math.max(8, Math.ceil(((a1 - a0) * R) / 3))
    return Array.from({ length: steps + 1 }, (_, i) => pt(a0 + ((a1 - a0) * i) / steps, R))
  }
  let s = pathTag(circle(R0, R0, R0 * 0.965), { fill: tok('kraft'), op: 0.05 })
  s += pathTag(circle(R0, R0, R0 - 2), { stroke: tok('kraft'), sw: 4, op: 0.16 })
  s += pathTag(poly(arc(R0 - 1, gapC + gapW, gapC + TAU - gapW)), { stroke: tok('orange-text'), sw: 1.4, op: 0.3 })
  ink.raw(`<g style="mix-blend-mode:var(--ll-blend)">${s}</g>`, 'top')
  ink.grow([0, 0, R0 * 2, R0 * 2])
  return ink.toSvg({ w: R0 * 2, h: R0 * 2, pad: 3 })
}

export interface CurlOpts extends PropOpts {
  color?: string
}

export function curlMarkup(r: Rng, id: string, c: number, color = 'sticky-yellow'): string {
  const col = tok(color)
  const jt = () => r.gauss(0, 0.2)
  const a: Pt = [0.2, c + jt()], b: Pt = [c + jt(), 0.2], m: Pt = [c * (0.42 + jt() * 0.05), c * (0.42 + jt() * 0.05)]
  let s = ''
  s += `<linearGradient id="${id}s" gradientUnits="userSpaceOnUse" x1="${num(m[0])}" y1="${num(m[1])}" x2="${num(m[0] - c * 0.16)}" y2="${num(m[1] - c * 0.16)}"><stop offset="0" stop-color="${tok('ink')}" stop-opacity=".16"/><stop offset="1" stop-color="${tok('ink')}" stop-opacity="0"/></linearGradient>`
  s += pathTag(poly([[a[0] - c * 0.12, a[1] - c * 0.12 + 2], [b[0] - c * 0.12 + 2, b[1] - c * 0.12], [m[0] - c * 0.16, m[1] - c * 0.16]], true), { fill: `url(#${id}s)` })
  s += `<linearGradient id="${id}d" gradientUnits="userSpaceOnUse" x1="${num(c / 2)}" y1="${num(c / 2)}" x2="${num(c * 0.86)}" y2="${num(c * 0.86)}"><stop offset="0" stop-color="${tok('ink')}" stop-opacity=".32"/><stop offset="1" stop-color="${tok('ink')}" stop-opacity="0"/></linearGradient>`
  s += pathTag(poly([a, b, [c + 1, c + 1]], true), { fill: `url(#${id}d)` })
  s += `<linearGradient id="${id}" gradientUnits="userSpaceOnUse" x1="${num(c / 2)}" y1="${num(c / 2)}" x2="${num(m[0])}" y2="${num(m[1])}"><stop offset="0" stop-color="${tok('photo')}" stop-opacity=".95"/><stop offset="1" stop-color="${col}" stop-opacity=".98"/></linearGradient>`
  s += pathTag(poly([a, b, m], true), { fill: `url(#${id})` })
  s += pathTag(poly([a, m, b]), { stroke: tok('ink'), sw: 0.6, op: 0.24 })
  s += pathTag(poly([a, b]), { stroke: tok('photo'), sw: 0.9, op: 0.75 })
  return s
}

export function stickyCurl(seed: string | number, c: number, o: CurlOpts = {}): InkResult {
  const ink = make(seed, o)
  ink.raw(curlMarkup(ink.next('curl'), `ll-cu${ink.seed.toString(36)}`, c, o.color), 'top')
  ink.grow([0, 0, c, c])
  return ink.toSvg({ w: c, h: c, pad: 3 })
}

export interface RulerOpts extends PropOpts {
  height?: number
}

export function ruler(seed: string | number, length: number, o: RulerOpts = {}): InkResult {
  const ink = make(seed, o)
  const h = o.height ?? 30
  const r = ink.next('ruler')
  const body = poly([[0.6, 0.5 + r.gauss(0, 0.15)], [length * 0.5, 0.2 + r.gauss(0, 0.2)], [length - 0.6, 0.5 + r.gauss(0, 0.15)], [length - 0.4, h - 0.5], [length * 0.5, h - 0.2 + r.gauss(0, 0.2)], [0.5, h - 0.6]], true)
  let d = ''
  for (let i = 0, x = 6; x < length - 5; i++, x += 6) {
    const long = i % 5 === 0
    d += `M${num(x + r.gauss(0, 0.08))} 0.8v${num((long ? h * 0.4 : h * 0.22) + r.gauss(0, 0.4))}`
  }
  ink.raw(
    pathTag(body, { fill: tok('kraft'), op: 0.96 }) +
      pathTag(`M1 ${num(h * 0.82)}H${num(length - 1)}`, { stroke: tok('orange-text'), sw: 0.6, op: 0.18 }) +
      pathTag(`M1 1.1H${num(length - 1)}`, { stroke: tok('photo'), sw: 1, op: 0.65 }) +
      pathTag(d, { stroke: tok('ink'), sw: 0.9, op: 0.78 }) +
      pathTag(body, { stroke: tok('ink'), sw: 0.7, op: 0.32 }),
    'top',
  )
  ink.grow([0, 0, length, h])
  return ink.toSvg({ w: length, h, pad: 3 })
}

export type FastenerKind = 'clip' | 'pin' | 'staple' | 'binder-clip'

import { makeRng } from '@/lib/ink/rng'

export type SheetShadowKind = 'hair' | 'loose' | 'lift' | 'slip' | 'card' | 'pad' | 'check' | 'paper' | 'sticky'

type Layer = readonly [dy: number, blur: number, spread: number, a: number]

export const SHADOW_LAYERS: Record<SheetShadowKind, readonly Layer[]> = {
  hair: [[1, 1.5, 0, 0.16]],
  loose: [[1, 2, 0, 0.12], [6, 16, -2, 0.12]],
  lift: [[1, 1.5, 0, 0.2], [7, 16, -4, 0.2]],
  slip: [[1, 1, 0, 0.2], [4, 8, -3, 0.2]],
  card: [[1, 1.5, 0, 0.2], [6, 11, -5, 0.24]],
  pad: [[1, 1.5, 0, 0.18], [10, 20, -8, 0.22]],
  check: [[1, 1.5, 0, 0.22], [6, 12, -5, 0.24]],
  paper: [[1, 1.5, 0, 0.2], [2, 5, -1, 0.1], [12, 22, -8, 0.2]],
  sticky: [[1, 1, 0, 0.2], [9, 10, -7, 0.34]],
}

const umber = (a: number) => `rgb(var(--ll-shade) / calc(${a} * var(--ll-shadow-k)))`
const px = (v: number) => (v === 0 ? '0' : `${Math.round(v * 100) / 100}px`)

export function sheetShadow(kind: SheetShadowKind = 'paper', lift = 1): string {
  if (lift === 1) return `var(--ll-shadow-${kind})`
  const L = SHADOW_LAYERS[kind]
  return L.map(([dy, blur, spread, a], i) => {
    const far = i > 0 || L.length === 1
    const k = far ? lift : Math.min(1, 0.4 + lift * 0.6)
    return `0 ${px(dy * k)} ${px(blur * k)} ${px(spread * (far ? lift : 1))} ${umber(Math.min(0.6, a * (far ? Math.min(1.35, 0.5 + lift * 0.5) : 1)))}`
  }).join(', ')
}

const CONTACT_BLUR = 2

export function contactShadow(kind: SheetShadowKind): { dy: number; a: number } | null {
  const first = SHADOW_LAYERS[kind][0]
  return first && first[1] <= CONTACT_BLUR ? { dy: first[0], a: first[3] } : null
}

export function farShadow(kind: SheetShadowKind, all = false): string {
  const far = SHADOW_LAYERS[kind].filter((l) => all || l[1] > CONTACT_BLUR)
  return far.length ? far.map(([dy, blur, spread, a]) => `0 ${px(dy)} ${px(blur)} ${px(spread)} ${umber(a)}`).join(', ') : 'none'
}

export type DropKind = 'sheet' | 'sticker' | 'tape' | 'prop'
const DROP: Record<DropKind, readonly (readonly [number, number, number])[]> = {
  sheet: [[1, 0.75, 0.22], [8, 8, 0.14]],
  sticker: [[1, 0.6, 0.26], [3, 3, 0.14]],
  tape: [[0.6, 0.8, 0.18]],
  prop: [[1, 0.8, 0.3], [3, 2.4, 0.16]],
}
export function dropShadow(kind: DropKind = 'sheet', lift = 1): string {
  if (lift === 1 && (kind === 'sheet' || kind === 'sticker')) return `var(--ll-drop-${kind})`
  return DROP[kind].map(([dy, blur, a]) => `drop-shadow(0 ${px(dy * lift)} ${px(blur * lift)} ${umber(Math.min(0.5, a))})`).join(' ')
}

export function tiltFor(seed: string | number, max = 0.6): number {
  const r = makeRng(`tilt:${seed}`)
  const sign = r.sign()
  return Math.round(sign * max * (0.25 + 0.75 * r()) * 100) / 100
}

export function tiltLimit(w: number, h: number, shift = 5, cap = 2): number {
  const L = Math.max(w, h, 1)
  const deg = (Math.asin(Math.min(1, (2 * shift) / L)) * 180) / Math.PI
  return Math.min(cap, Math.max(0.05, Math.round(deg * 20) / 20))
}

export function tiltVars(deg: number): Record<'--ll-tilt', string> {
  return { '--ll-tilt': `${deg}deg` }
}

export function tileOffsets(seed: string | number, sizes: readonly (readonly [number, number])[]): string {
  const r = makeRng(`tex:${seed}`)
  return sizes.map(([w, h]) => `${-Math.floor(r() * w)}px ${-Math.floor(r() * h)}px`).join(', ')
}

// 沿用上游纸面拆分算法，保留纸张阴影和绘制图层的先后顺序。


import { computed, toValue, type CSSProperties, type MaybeRefOrGetter } from "vue"
import { defineUi } from "@/lib/component"

import { inkViewBox } from "@/lib/ink/builder"
import { faceClip, faceLook, hasFace, splitFaces, tilesOf, type FaceSpec } from "@/lib/ink/paper/faces"
import { farShadow } from "@/lib/ink/paper/shadows"
import { InkSvg, InkTiles, useInkCore, type Frame, type UseInkOptions } from "@/lib/ink/vue"
import type { InkLayerName } from "@/lib/ink/recipes"

type Piece = { type: "svg"; groups: Array<[layer: InkLayerName, markup: string]> } | { type: "face"; spec: FaceSpec; layer: InkLayerName }

function piecesOf(frame: Frame): { pieces: Piece[]; casts: FaceSpec[] } {
  const out: Piece[] = []
  const casts: FaceSpec[] = []
  let cur: Extract<Piece, { type: "svg" }> | null = null
  for (const layer of frame.layers) {
    for (const part of splitFaces(frame.parts[layer] ?? "")) {
      if (typeof part === "string") {
        if (!cur) out.push((cur = { type: "svg", groups: [] }))
        cur.groups.push([layer, part])
      } else if (part.paper === false) {
        casts.push(part)
      } else {
        cur = null
        casts.push(part)
        out.push({ type: "face", spec: part, layer })
      }
    }
  }
  if (!out.some((p) => p.type === "svg") || out[out.length - 1].type === "face") out.push({ type: "svg", groups: [] })
  return { pieces: out, casts: casts.filter((c) => c.cast) }
}

export const SheetLayers = defineUi<{ kind: string; frame: Frame; still?: boolean }>("SheetLayers", ["kind", "frame", "still"], props => () => {
 const { kind, frame, still } = props
  const { w, h, pad } = frame
  const { pieces, casts } = piecesOf(frame)
  const at = (x: number, y: number, ww: number, hh: number): CSSProperties => ({ left: `calc(50% - ${x}px)`, top: `calc(50% - ${y}px)`, width: `${ww}px`, height: `${hh}px` })
  const faces = pieces.filter((p): p is Extract<Piece, { type: "face" }> => p.type === "face")
  return (
    <>
      {faces.length ? <InkTiles tiles={tilesOf(faces.map((f) => f.spec.stock))} /> : null}
      {casts.map(({ cast }, i) => {
        const [t, r, b, l] = cast!.inset
        return (
          <span
            key={`shadow${i}`}
            data-slot="paper-shadow"
            aria-hidden="true"
            class="ll-face-shadow"
            style={{
              ...at(w / 2 - l, h / 2 - t, w - l - r, h - t - b),
              boxShadow: farShadow(cast!.kind, !!cast!.radius),
              ...(cast!.radius ? { borderRadius: cast!.radius.map((v) => `${v}px`).join(" ") } : {}),
            }}
          />
        )
      })}
      {pieces.map((p, i) => {
        if (p.type === "face") {
          const look = faceLook(p.spec.stock, p.spec.seed, p.spec.veil !== false)
          return (
            <span
              key={`face${i}`}
              data-slot="paper-face"
              data-layer={p.layer === "rest" ? undefined : p.layer}
              aria-hidden="true"
              class={`ll-face ${look.className}`}
              style={
                {
                  ...at(w / 2 + pad, h / 2 + pad, w + 2 * pad, h + 2 * pad),
                  ...look.vars,
                  "--ll-face-path": faceClip(p.spec, pad, pad),
                } as CSSProperties
              }
            />
          )
        }
        const groups = p.groups.some(([layer]) => layer === "rest") ? p.groups : ([["rest", ""], ...p.groups] as typeof p.groups)
        return (
          <svg
            key={`svg${i}`}
            data-ink={kind}
            data-still={still ? "" : undefined}
            aria-hidden="true"
            focusable="false"
            class="pointer-events-none absolute"
            viewBox={inkViewBox(frame)}
            preserveAspectRatio="none"
            style={{ position: "absolute", pointerEvents: "none", ...at(w / 2 + pad, h / 2 + pad, w + 2 * pad, h + 2 * pad), overflow: "visible", zIndex: -1 }}
          >
            {groups.map(([layer, markup]) => (
              <g key={layer} data-layer={layer} innerHTML={markup} />
            ))}
          </svg>
        )
      })}
    </>
  )
})

// 纸面由 Vue computed 驱动，尺寸或绘制参数变化时重新组合纸面和笔触图层。
export function useInkFaces<P>(source: MaybeRefOrGetter<UseInkOptions<P>>) {
  const core = useInkCore(source)
  const node = computed(() => {
    const frame = core.frame.value
    if (!frame) return null
    const options = toValue(source)
    const kind = options.kind ?? options.recipe.kind
    const faced = frame.layers.some(layer => hasFace(frame.parts[layer] ?? ''))
    return faced ? <SheetLayers key="ink" kind={kind} frame={frame} still={core.still.value} /> : <InkSvg key="ink" kind={kind} frame={frame} still={core.still.value} />
  })
  return { ...core, node }
}

