  photo: def({ name: 'photo', label: 'Photo', stockClass: 'll-stock-photo', tooth: 'fine', shadow: 'card', shadowClass: 'll-sheet-card', edge: 'cut', rules: 'window', tilt: 1.5 }),
  parchment: def({ name: 'parchment', label: 'Parchment', base: 'paper', tint: ['kraft', 0.34], stockClass: '', tooth: 'cold', shadow: 'paper', shadowClass: '', edge: 'deckle', rules: 'none', tilt: 0.6 }),
  receipt: def({ name: 'receipt', label: 'Receipt', stockClass: 'll-stock-photo', tooth: 'none', shadow: 'slip', shadowClass: 'll-sheet-slip', edge: { top: 'zig', bottom: 'zig' }, rules: 'none', tilt: 0.9 }),
}

export const STOCK_NAMES = Object.keys(STOCKS) as StockName[]

export function stockOf(name: string | undefined): StockDef {
  return (name && (STOCKS as Record<string, StockDef>)[name]) || STOCKS.paper
}

export const TOOTH_TILES: Record<Tooth, readonly (readonly [tile: string, w: number, h: number])[]> = {
  cold: [['fibre', 240, 240], ['relief', 192, 192], ['cloud', 720, 720]],
  fine: [['fibre', 240, 240], ['slip', 128, 128], ['cloud', 720, 720]],
  kraft: [['fibre', 240, 240], ['kraft', 192, 96], ['cloud', 720, 720]],
  none: [['cloud', 720, 720]],
}

export type CssDecls = Record<string, string>

interface BgLayer {
  image: string
  size: string
  position?: string
  repeat?: string
  origin?: string
  clip?: string
}

function layersToDecls(layers: BgLayer[]): CssDecls {
  const join = (f: (l: BgLayer) => string) => layers.map(f).join(', ')
  return {
    backgroundImage: join((l) => l.image),
    backgroundSize: join((l) => l.size),
    backgroundPosition: join((l) => l.position ?? '0 0'),
    backgroundRepeat: join((l) => l.repeat ?? 'repeat'),
    backgroundOrigin: join((l) => l.origin ?? 'border-box'),
    backgroundClip: join((l) => l.clip ?? 'border-box'),
  }
}

const up = (y: number, geo: RuleGeometry): string => (geo.offset ? `calc(${y}px - var(${RULE_OFFSET_VAR}, ${geo.offset}px))` : `${y}px`)
const upClamped = (y: number, geo: RuleGeometry): string => (geo.offset ? `max(0px, ${up(y, geo)})` : `${y}px`)

const soft = (token: string, pct: number) => `color-mix(in srgb, var(--ll-${token}) ${pct}%, transparent)`

const hline = (color: string, w = 0.9) => `linear-gradient(to bottom, transparent calc(100% - ${w}px), ${color} calc(100% - ${w}px))`
const vline = (color: string, x: number, w = 1.2, fromRight = false) => {
  const at = (v: number) => (fromRight ? `calc(100% - ${x - v}px)` : `${x + v}px`)
  return `linear-gradient(to right, transparent ${at(-w / 2)}, ${color} ${at(-w / 2)} ${at(w / 2)}, transparent ${at(w / 2)})`
}

export interface RulesOpts {
  calm?: boolean
  first?: number
}

export const RULE_OFFSET_VAR = '--ll-rule-offset'

export const KALAM_BASELINE = 0.266

export const ruleOffsetFor = (pitch: number, fs = 17): number => Math.round(pitch / 2 - KALAM_BASELINE * fs - 1.95)

export interface RulesLayer {
  style: CssDecls
  pitch: number
  geo: RuleGeometry
}

export interface RuleGeometry {
  kind: RuleName
  pitch: number
  first: number
  offset: number
  margin?: number
  major?: number
  cols?: readonly [number, number]
}

export function ruleGeometry(kind: RuleName, o: RulesOpts = {}): RuleGeometry {
  const calm = !!o.calm
  switch (kind) {
    case 'ruled':
    case 'ruled-hand': {
      const pitch = calm ? 24 : 28
      return { kind, pitch, first: o.first ?? 16 + pitch, offset: ruleOffsetFor(pitch), margin: calm ? undefined : 44 }
    }
    case 'pad':
      return { kind, pitch: 30, first: o.first ?? 40, offset: ruleOffsetFor(30) }
    case 'index':
      return { kind, pitch: 30, first: o.first ?? 49, offset: ruleOffsetFor(30) }
    case 'graph':
      return { kind, pitch: 16, first: 0, offset: 0, major: 64 }
    case 'dots':
      return { kind, pitch: 20, first: 10, offset: 0, major: 100 }
    case 'ledger': {
      const pitch = calm ? 22 : 24
      return { kind, pitch, first: 40, offset: ruleOffsetFor(pitch, 15), cols: [54, 70] }
    }
    case 'window':
      return { kind, pitch: 0, first: 0, offset: 0 }
    default:
      return { kind: 'none', pitch: 0, first: 0, offset: 0 }
  }
}

export function rulesLayer(kind: RuleName, o: RulesOpts = {}): RulesLayer | null {
  if (kind === 'none' || kind === 'ruled-hand') return null
  const calm = !!o.calm
  const geo = ruleGeometry(kind, o)
  const drift = 'linear-gradient(90deg, rgb(0 0 0 / .86), rgb(0 0 0) 19%, rgb(0 0 0 / .8) 47%, rgb(0 0 0 / .96) 71%, rgb(0 0 0 / .84))'
  const withMask = (style: CssDecls): CssDecls => (calm ? style : { ...style, maskImage: drift, WebkitMaskImage: drift })
  if (kind === 'window') {
    return {
      pitch: 0,
      geo,
      style: {
        inset: '10px 10px 26%',
        backgroundColor: soft('paper-shade', 55),
        boxShadow: 'inset 0 2px 4px rgb(var(--ll-shade) / calc(0.26 * var(--ll-shadow-k))), inset 0 0 0 1px rgb(var(--ll-shade) / calc(0.1 * var(--ll-shadow-k)))',
      },
    }
  }
  if (kind === 'ruled' || kind === 'pad' || kind === 'index') {
    const { pitch, first } = geo
    const rule = soft(kind === 'pad' ? 'pad-rule' : 'rule-blue', kind === 'pad' ? 100 : 82)
    const red = soft('rule-red', 88)
    const layers: BgLayer[] = []
    if (geo.margin !== undefined) layers.push({ image: vline(red, geo.margin), size: '100% 100%', repeat: 'no-repeat' })
    if (kind === 'index') layers.push({ image: hline(red, 1.2), size: `100% ${up(first + 1, geo)}`, repeat: 'no-repeat' })
    const blueFirst = kind === 'index' ? first + pitch : first
    layers.push({ image: hline(rule), size: `100% ${pitch}px`, position: `0 ${up(blueFirst - pitch + 1, geo)}`, repeat: 'repeat-y', clip: 'content-box' })
    return { pitch, geo, style: withMask({ ...layersToDecls(layers), paddingTop: upClamped(Math.max(0, kind === 'index' ? first + 2 : blueFirst - 1), geo) }) }
  }
  if (kind === 'graph') {
    const fine = soft('check-rule', 46)
    const bold = soft('check-rule', 72)
    return {
      pitch: 16,
      geo,
      style: withMask({
        ...layersToDecls([
          { image: `linear-gradient(to right, ${bold} 1px, transparent 1px)`, size: '64px 64px', position: '0 0' },
          { image: `linear-gradient(to bottom, ${bold} 1px, transparent 1px)`, size: '64px 64px', position: '0 0' },
          { image: `linear-gradient(to right, ${fine} 1px, transparent 1px)`, size: '16px 16px', position: '0 0' },
          { image: `linear-gradient(to bottom, ${fine} 1px, transparent 1px)`, size: '16px 16px', position: '0 0' },
        ]),
      }),
    }
  }
  if (kind === 'dots') {
    const dot = `radial-gradient(circle at center, ${soft('pencil-mark', 90)} 0 .8px, transparent 1.15px)`
    const big = `radial-gradient(circle at center, ${soft('pencil', 70)} 0 1.05px, transparent 1.5px)`
    return {
      pitch: 20,
      geo,
      style: layersToDecls([
        { image: big, size: '100px 100px', position: '10px 10px' },
        { image: dot, size: '20px 20px', position: '10px 10px' },
      ]),
    }
  }
  const pitch = geo.pitch
  const line = soft('check-rule', 62)
  const strong = soft('check-rule', 100)
  const [qty, total] = geo.cols as readonly [number, number]
  return {
    pitch,
    geo,
    style: withMask({
      ...layersToDecls([
        { image: vline(strong, qty, 1), size: '100% 100%', repeat: 'no-repeat' },
        { image: vline(strong, total, 1, true), size: '100% 100%', repeat: 'no-repeat' },
        { image: hline(strong, 1.1), size: `100% ${up(40, geo)}`, position: '0 0', repeat: 'no-repeat' },
        { image: hline(line), size: `100% ${pitch}px`, position: `0 ${up(40 - pitch + 1, geo)}`, repeat: 'repeat-y', clip: 'content-box' },
      ]),
      paddingTop: upClamped(40, geo),
    }),
  }
}

export const stockShadow = (name: string | undefined, lift = 1): string => sheetShadow(stockOf(name).shadow, lift)

import { n } from '@/lib/ink/paint'
import { highlight } from '@/lib/ink/fills'
import { underline } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import { faceMark } from '@/lib/ink/paper/faces'
import { contactShadow, farShadow, type SheetShadowKind } from '@/lib/ink/paper/shadows'
import { stockOf, type StockName } from '@/lib/ink/paper/stocks'
import type { Rng } from '@/lib/ink/rng'
import type { Pt } from '@/lib/ink/types'

export const tok = (name: string) => `var(--ll-${name})`
export const num = (v: number) => n(v, 10)

export interface PathAttrs {
  fill?: string
  stroke?: string
  sw?: number
  op?: number
  transform?: string
  cap?: 'round' | 'butt'
  extra?: string
}

export function pathTag(d: string, a: PathAttrs): string {
  let s = `<path d="${d}"`
  s += a.fill ? ` fill="${a.fill}"` : ' fill="none"'
  if (a.stroke) s += ` stroke="${a.stroke}" stroke-width="${n(a.sw ?? 1)}" stroke-linecap="${a.cap ?? 'round'}" stroke-linejoin="round"`
  if (a.op !== undefined && a.op < 0.995) s += ` ${a.stroke && !a.fill ? 'stroke' : 'fill'}-opacity="${n(a.op, 100)}"`
  if (a.transform) s += ` transform="${a.transform}"`
  if (a.extra) s += ` ${a.extra}`
  return s + '/>'
}

export const polyD = (pts: readonly Pt[], close = false) => 'M' + pts.map((p) => `${num(p[0])} ${num(p[1])}`).join('L') + (close ? 'Z' : '')

export const circleD = (cx: number, cy: number, r: number) =>
  `M${num(cx - r)} ${num(cy)}a${num(r)} ${num(r)} 0 1 0 ${num(2 * r)} 0a${num(r)} ${num(r)} 0 1 0 ${num(-2 * r)} 0z`

export const ellipseD = (cx: number, cy: number, rx: number, ry: number) =>
  `M${num(cx - rx)} ${num(cy)}a${num(rx)} ${num(ry)} 0 1 0 ${num(2 * rx)} 0a${num(rx)} ${num(ry)} 0 1 0 ${num(-2 * rx)} 0z`

export const mirrorX = (w: number, inner: string) => `<g transform="translate(${num(w)} 0) scale(-1 1)">${inner}</g>`

export const MIRROR = (w: number) => `translate(${num(w)} 0) scale(-1 1)`

export function holePunch(id: string, cx: number, cy: number, r: number, tilt = 0): string {
  const rx = r * 1.03
  const ry = r * 0.97
  const rot = `rotate(${n(tilt)} ${num(cx)} ${num(cy)})`
  const hole = ellipseD(cx, cy, rx, ry)
  let s = `<clipPath id="${id}"><path d="${hole}" transform="${rot}"/></clipPath>`
  s += pathTag(hole, { fill: tok('desk-deep'), transform: rot })
  s += `<g clip-path="url(#${id})">${pathTag(circleD(cx, cy, r * 1.4), { fill: tok('ink'), op: 0.4 })}${pathTag(circleD(cx + r * 0.34, cy + r * 0.4, r * 0.98), { fill: tok('desk-deep') })}</g>`
  const a0 = -0.15 * Math.PI
  const a1 = 0.62 * Math.PI
  const p = (a: number): [number, number] => [cx + Math.cos(a) * (r - 0.4), cy + Math.sin(a) * (r - 0.4)]
  const [x0, y0] = p(a0)
  const [x1, y1] = p(a1)
  s += pathTag(`M${num(x0)} ${num(y0)}A${num(r - 0.4)} ${num(r - 0.4)} 0 0 1 ${num(x1)} ${num(y1)}`, { stroke: tok('photo'), sw: 1.1, op: 0.85 })
  s += pathTag(hole, { stroke: tok('ink'), sw: 0.7, op: 0.3, transform: rot })
  return s
}

export function reinforcement(cx: number, cy: number, r: number): string {
  const R = r + 5.4
  const ring = `${circleD(cx, cy, R)}${circleD(cx, cy, r - 0.3)}`
  let s = pathTag(ring, { fill: tok('ink'), op: 0.16, transform: 'translate(.7 1.2)', extra: 'fill-rule="evenodd"' })
  s += pathTag(ring, { fill: tok('photo'), extra: 'fill-rule="evenodd"' })
  s += pathTag(circleD(cx, cy, R - 0.4), { stroke: tok('ink'), sw: 0.7, op: 0.24 })
  s += pathTag(circleD(cx, cy, (R + r) / 2), { stroke: tok('paper-shade'), sw: 0.6, op: 0.7 })
  return s
}

export interface PaperFillOpts {
  stock: StockName
  id?: string
  edge?: number
  evenodd?: boolean
  shadow?: boolean | SheetShadowKind
  far?: boolean
  inset?: readonly [number, number, number, number]
}

export function paperFill(seed: number, d: string, o: PaperFillOpts): string {
  const S = stockOf(o.stock)
  const gid = `ll-pf${seed.toString(36)}${o.id ?? ''}`
  const kind = o.shadow === undefined || o.shadow === false ? 'none' : o.shadow === true ? S.shadow : o.shadow
  const contact = kind === 'none' ? null : contactShadow(kind)
  const cast = kind !== 'none' && o.far !== false && farShadow(kind) !== 'none'
  let s = `<defs><path id="${gid}" d="${d}"${o.evenodd ? ' fill-rule="evenodd"' : ''}/></defs>`
  if (contact) s += `<use href="#${gid}" transform="translate(0 ${num(contact.dy)})" fill="${tok('umber')}" fill-opacity="${contact.a}" opacity="var(--ll-shadow-k)"/>`
  s += faceMark({ d, stock: o.stock, seed, veil: false, ...(o.evenodd ? { evenodd: true } : {}), ...(cast ? { cast: { kind: kind as SheetShadowKind, inset: o.inset ?? [1, 1, 1, 1] } } : {}) })
  s += `<use href="#${gid}" fill="none" stroke="${tok('ink')}" stroke-opacity="${o.edge ?? 0.14}" stroke-width=".6"/>`
  return s
}

export function litEdge(d: string, op = 0.7): string {
  return pathTag(d, { stroke: tok('photo'), sw: 1, op, transform: 'translate(0 -.6)' })
}

export type TitleMark = 'single' | 'double' | 'wavy' | 'highlight'

export interface TitleMarkParams {
  kind: TitleMark
  tone?: 'ink' | 'you' | 'red' | 'marker'
}

const MARK_PEN = { ink: 'ink', you: 'blue', red: 'redfelt', marker: 'terracotta' } as const

export const titleMarkRecipe = defineRecipe<TitleMarkParams>({
  id: 'paper-set-title-mark',
  kind: 'mark',
  layers: ['rest'],
  pad: 10,
  draw(ink, { w, h }, { kind, tone = 'ink' }, ctx) {
    ink.layer('rest', () => {
      if (kind === 'highlight') {
        highlight(ink, -3, h * 0.46, w + 6, h * 0.42, { pen: 'hi' })
        return
      }
      const y = h - 4
      if (ctx.calm) {
        underline(ink, 0, y, w, { kind: 'single', pen: 'pencil.fine' })
        return
      }
      underline(ink, -2, y, w + 4, { kind, pen: MARK_PEN[tone] })
    })
  },
})

export function stackSvg(w: number, h: number, count: number, r: Rng, id: string, fills: readonly [string, string] = ['paper', 'paper-shade']): string {
  if (count < 1) return ''
  const step = 2.6
  let s = `<clipPath id="${id}c"><path d="M-60 -60H${num(w + 120)}V${num(h + 120)}H-60zM0 0V${num(h)}H${num(w)}V0z" clip-rule="evenodd"/></clipPath>`
  let sheets = ''
  for (let i = count; i >= 1; i--) {
    const d = i * step
    const rot = r.gauss(0, 0.18) * i
    const x0 = 3 + i * 1.4
    const y0 = 3 + i * 1.4
    const path = `M${num(x0)} ${num(y0)}H${num(w + d)}V${num(h + d)}H${num(x0)}z`
    sheets += `<g transform="rotate(${num(rot)} ${num(x0)} ${num(y0)})">`
    if (i === count) {
      sheets += pathTag(path, { fill: tok('ink'), op: 0.1, transform: 'translate(1.4 4)' }) + pathTag(path, { fill: tok('ink'), op: 0.14, transform: 'translate(.6 1.6)' })
    }
    sheets += pathTag(path, { fill: i % 2 ? tok(fills[1]) : tok(fills[0]) })
    sheets += pathTag(path, { stroke: tok('ink'), sw: 0.6, op: 0.22 })
    sheets += pathTag(`M${num(x0 + 2)} ${num(h + d - 0.6)}H${num(w + d - 1)}M${num(w + d - 0.6)} ${num(y0 + 2)}V${num(h + d - 1)}`, { stroke: tok('photo'), sw: 0.8, op: 0.7 })
    sheets += '</g>'
  }
  s += `<g clip-path="url(#${id}c)">${sheets}</g>`
  return s
}
